#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请用 sudo bash'; exit 1; }
exec 9>/run/football-reliability-install.lock
flock -n 9 || { echo '更新正在进行'; exit 1; }
backup=/var/backups/football-reliability-$(date +%Y%m%d-%H%M%S)
mkdir -p "$backup"
for directory in football-audit football-web football-injury-bridge; do cp -a "/opt/$directory" "$backup/$directory"; done
units='football-quality-audit football-injury-bridge football-settlement-refresh'
for unit in $units; do
 if systemctl is-active --quiet "$unit.timer"; then echo "$unit.timer" >> "$backup/timers"; fi
 systemctl stop "$unit.timer" 2>/dev/null || true
done
resume() { if [[ -f "$backup/timers" ]]; then while read -r timer; do systemctl start "$timer" || true; done < "$backup/timers"; fi; }
rollback() { for directory in football-audit football-web football-injury-bridge; do cp -a "$backup/$directory/." "/opt/$directory/"; done; systemctl restart football-web.service || true; resume; echo "安装失败，已恢复代码：$backup"; }
trap rollback ERR
for unit in $units; do
 for attempt in $(seq 1 90); do
  state=$(systemctl show "$unit.service" -p ActiveState --value 2>/dev/null || true)
  [[ "$state" != active && "$state" != activating ]] && break
  if [[ $attempt -eq 90 ]]; then resume; echo '任务仍在运行，请稍后重试'; exit 1; fi
  sleep 2
 done
done
python3 - <<'FILES'
from pathlib import Path
import base64,os,grp,py_compile
for name,data in {'/opt/football-audit/reliability.py': '', '/opt/football-audit/refresh_results.py': '', '/opt/football-web/selection_view.py': ''}.items():
 p=Path(name);t=p.with_suffix('.new');t.write_bytes(base64.b64decode(data));py_compile.compile(str(t),doraise=True);t.chmod(0o640);os.chown(t,0,grp.getgrnam('footballweb' if 'football-web/' in name else 'football').gr_gid);os.replace(t,p)
FILES
python3 - <<'PATCH'
from pathlib import Path
import os,py_compile

def patch(path,marker,anchor,replacement):
 p=Path(path);s=p.read_text()
 if marker in s:return
 if s.count(anchor)!=1:raise RuntimeError('Unsupported installed version: '+path)
 s=s.replace(anchor,replacement);st=p.stat();t=p.with_suffix('.new');t.write_text(s)
 if p.suffix=='.py':py_compile.compile(str(t),doraise=True)
 os.chmod(t,st.st_mode);os.chown(t,st.st_uid,st.st_gid);os.replace(t,p)
patch('/opt/football-audit/audit.py','# reliability-v1',"p=ROOT/'reports/quality-audit.json';",'''# reliability-v1
try:
 from reliability import extend
 with psycopg.connect('dbname=football user=football host=/var/run/postgresql',row_factory=dict_row,options='-c search_path=football_v1 -c statement_timeout=20000 -c default_transaction_read_only=on') as checkdb:
  extend(out,checkdb,games,NOW)
except Exception as e:
 out['paired_evaluation']={'status':'failed','error_type':type(e).__name__,'auto_promotion':False}
p=ROOT/'reports/quality-audit.json';''')
patch('/opt/football-web/web.py','# reliability-view-v1','  return result\n',"  # reliability-view-v1\n  from selection_view import assess\n  for match in rows:match['analysis_screen']=assess(match)\n  return result\n")
patch('/opt/football-injury-bridge/sync_injuries.py','# reliability-export-v1',"  out['matches'].append(item)","  # reliability-export-v1\n  item['analysis_screen']=m.get('analysis_screen',{})\n  out['matches'].append(item)")
patch('/opt/football-web/app.js','// reliability-screen-v1','for(const s of m.odds_sources)',"""// reliability-screen-v1
const sc=m.analysis_screen; if(sc){const box=node('div',undefined,'odds');box.append(node('strong','分析筛选：暂不自动推荐'));for(const reason of sc.reasons||[])box.append(node('p',reason));card.append(box);}
for(const s of m.odds_sources)""")

PATCH
systemctl restart football-web.service
systemctl start football-quality-audit.service
python3 - <<'VERIFY'
import json
r=json.load(open('/opt/football/reports/quality-audit.json'))
assert r['paired_evaluation']['status']=='collecting_future_evidence', '新旧模型比较检查失败'
assert 'settlement_check' in r
print('RELIABILITY_AUDIT_OK paired='+str(r['paired_evaluation']['enrolled']))
import urllib.request,time
c=json.load(open('/etc/football-web/access.json'))
op=urllib.request.build_opener(urllib.request.ProxyHandler({}))
for attempt in range(8):
 try:
  req=urllib.request.Request('http://127.0.0.1:8787/ui-api/data',headers={'Authorization':'Bearer '+c['api_key']})
  with op.open(req,timeout=30) as response:data=json.load(response)
  assert all('analysis_screen' in m for m in data['matches'])
  print('RELIABILITY_VIEW_OK matches='+str(len(data['matches'])))
  break
 except Exception:
  if attempt==7:raise SystemExit('看板接口验证失败')
  time.sleep(1)
VERIFY
cat > /etc/systemd/system/football-settlement-refresh.service <<'UNIT'
[Unit]
Description=Refresh overdue paper result dates
[Service]
Type=oneshot
User=football
Group=football
ExecStart=/opt/football/.venv/bin/python /opt/football-audit/refresh_results.py
TimeoutStartSec=180
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/opt/football/reports /opt/football/data
UNIT
cat > /etc/systemd/system/football-settlement-refresh.timer <<'UNIT'
[Timer]
OnBootSec=5min
OnUnitActiveSec=1h
[Install]
WantedBy=timers.target
UNIT
systemctl daemon-reload
resume
systemctl enable --now football-settlement-refresh.timer
trap - ERR
systemctl start --no-block football-settlement-refresh.service football-github-sync.service football-injury-bridge.service
echo 'RELIABILITY_UPDATE_OK：赛前双模型留档、未结算诊断、分析筛选已安装。'
echo '赛果每小时最多回查3个日期，不消耗伤停API额度；新模型比较需积累之后的比赛，不自动替换。'
echo "备份：$backup"
